-- Root material is independently reconstructible after a tracking write.
-- name: ListDownloadWatchRootMaterial :many
SELECT jsonb_build_object('client_id',c.id,'client_version',c.updated_at,'client_stamp',encode(sha256(convert_to(jsonb_build_object('id',c.id,'type',c.client_type,'version',c.updated_at AT TIME ZONE 'UTC','url',c.url,'username',c.username,'password',c.password_encrypted,'mapping',c.remote_path_map)::text,'UTF8')),'hex'),'mapping',CASE WHEN pg_column_size(c.remote_path_map)<=65536 THEN c.remote_path_map ELSE NULL END,'client_type',c.client_type,'root_id',r.id,'root_path',r.path,'generation',r.generation,'media_type',r.media_type,'marker',r.marker_filename,'online',r.health='online','baseline_completed',r.baseline_completed,'baseline_id',b.scan_run_id,'device',b.root_device,'inode',b.root_inode,'baseline_path',b.expected_path,'baseline_media_type',b.expected_media_type,'baseline_marker',b.expected_marker_filename) AS material FROM download_client c CROSS JOIN library_root r
LEFT JOIN LATERAL (SELECT f.scan_run_id,f.root_device,f.root_inode,f.expected_path,f.expected_media_type,f.expected_marker_filename FROM scan_finalization f JOIN scan_run s ON s.id=f.scan_run_id WHERE f.root_id=r.id AND s.generation=r.generation AND s.state='succeeded' AND f.completed_at IS NOT NULL ORDER BY s.created_at,s.id LIMIT 1) b ON true
WHERE ((c.id::text || ':' || r.id::text) > sqlc.arg(after_key)::text OR (sqlc.arg(resume_current)::boolean AND (c.id::text || ':' || r.id::text) = sqlc.arg(after_key)::text))
 AND EXISTS (SELECT 1 FROM download_task t WHERE t.client_id=c.id AND t.state='tracking' AND (EXISTS(SELECT 1 FROM download_requirement d JOIN media_unit u ON u.id=d.unit_id JOIN media m ON m.id=u.media_id WHERE d.operation_id=t.operation_id AND d.root_id=r.id AND d.state='pending' AND d.released_at IS NULL AND NOT u.retired AND m.media_type=r.media_type AND (m.media_type='movie' OR (m.media_type='tv' AND EXISTS(SELECT 1 FROM episode_execution_authority ea WHERE ea.operation_id=t.operation_id AND ea.unit_id=u.id AND ea.root_id=r.id AND ea.client_id=t.client_id AND ea.candidate_id=t.candidate_id)))) AND NOT EXISTS(SELECT 1 FROM download_requirement x JOIN media_unit ux ON ux.id=x.unit_id JOIN media mx ON mx.id=ux.media_id JOIN library_root rx ON rx.id=x.root_id WHERE x.operation_id=t.operation_id AND x.state='pending' AND x.released_at IS NULL AND (x.root_id<>r.id OR ux.retired OR (x.submission_fence IS NULL AND NOT EXISTS(SELECT 1 FROM acquisition_reservation a WHERE a.operation_id=t.operation_id AND a.unit_id=ux.id AND a.candidate_id=t.candidate_id AND a.task_id=t.id AND a.source_root_id=rx.id AND a.source_generation=rx.generation AND a.source_stamp<>'' AND NOT a.legacy_conflict AND a.released_at IS NULL)) OR (x.submission_fence IS NOT NULL AND (jsonb_typeof(x.submission_fence) IS DISTINCT FROM 'object' OR (x.submission_fence->>'candidate_id') IS DISTINCT FROM t.candidate_id::text OR (x.submission_fence->>'unit_id') IS DISTINCT FROM ux.id::text OR (x.submission_fence->>'root_id') IS DISTINCT FROM rx.id::text OR (x.submission_fence->>'root_generation') IS DISTINCT FROM rx.generation::text OR (x.submission_fence->>'unit_metadata_version') IS DISTINCT FROM ux.metadata_version::text OR (x.submission_fence->>'media_metadata_version') IS DISTINCT FROM mx.metadata_version::text)))) AND NOT EXISTS(SELECT 1 FROM automatic_tv_execution_authority WHERE operation_id=t.operation_id) AND NOT EXISTS(SELECT 1 FROM automatic_tv_submission_preparation WHERE operation_id=t.operation_id) AND NOT EXISTS(SELECT 1 FROM download_requirement WHERE operation_id=t.operation_id AND (submission_fence->>'kind'='automatic_tv_episode_v1' OR submission_fence->>'goal'='upgrade')) AND NOT EXISTS(SELECT 1 FROM complete_tv_execution_authority WHERE operation_id=t.operation_id) AND NOT EXISTS(SELECT 1 FROM complete_tv_submission_preparation WHERE operation_id=t.operation_id) AND NOT EXISTS(SELECT 1 FROM complete_tv_submission_unit cu WHERE cu.task_id=t.id) AND NOT EXISTS(SELECT 1 FROM movie_upgrade_authority WHERE operation_id=t.operation_id) AND NOT EXISTS(SELECT 1 FROM unit_reservation WHERE operation_id=t.operation_id AND purpose='upgrade')))
ORDER BY c.id,r.id LIMIT sqlc.arg(page_size)::int;

-- name: GetDownloadWatchRootMaterial :one
SELECT jsonb_build_object('client_id',c.id,'client_version',c.updated_at,'client_stamp',encode(sha256(convert_to(jsonb_build_object('id',c.id,'type',c.client_type,'version',c.updated_at AT TIME ZONE 'UTC','url',c.url,'username',c.username,'password',c.password_encrypted,'mapping',c.remote_path_map)::text,'UTF8')),'hex'),'mapping',CASE WHEN pg_column_size(c.remote_path_map)<=65536 THEN c.remote_path_map ELSE NULL END,'client_type',c.client_type,'root_id',r.id,'root_path',r.path,'generation',r.generation,'media_type',r.media_type,'marker',r.marker_filename,'online',r.health='online','baseline_completed',r.baseline_completed,'baseline_id',b.scan_run_id,'device',b.root_device,'inode',b.root_inode,'baseline_path',b.expected_path,'baseline_media_type',b.expected_media_type,'baseline_marker',b.expected_marker_filename) AS material FROM download_client c CROSS JOIN library_root r
LEFT JOIN LATERAL (SELECT f.scan_run_id,f.root_device,f.root_inode,f.expected_path,f.expected_media_type,f.expected_marker_filename FROM scan_finalization f JOIN scan_run s ON s.id=f.scan_run_id WHERE f.root_id=r.id AND s.generation=r.generation AND s.state='succeeded' AND f.completed_at IS NOT NULL ORDER BY s.created_at,s.id LIMIT 1) b ON true
WHERE c.id=sqlc.arg(client_id)::uuid AND r.id=sqlc.arg(root_id)::uuid;

-- name: ListDownloadWatchTaskMaterial :many
SELECT jsonb_build_object('task_id',t.id,'operation_id',t.operation_id,'client_id',t.client_id,'state',t.state,'save_path',t.save_path,'content_path',t.content_path,'eligible',(EXISTS(SELECT 1 FROM download_requirement d JOIN media_unit u ON u.id=d.unit_id JOIN media m ON m.id=u.media_id WHERE d.operation_id=t.operation_id AND d.root_id=r.id AND d.state='pending' AND d.released_at IS NULL AND NOT u.retired AND m.media_type=r.media_type AND (m.media_type='movie' OR (m.media_type='tv' AND EXISTS(SELECT 1 FROM episode_execution_authority ea WHERE ea.operation_id=t.operation_id AND ea.unit_id=u.id AND ea.root_id=r.id AND ea.client_id=t.client_id AND ea.candidate_id=t.candidate_id)))) AND NOT EXISTS(SELECT 1 FROM download_requirement x JOIN media_unit ux ON ux.id=x.unit_id JOIN media mx ON mx.id=ux.media_id JOIN library_root rx ON rx.id=x.root_id WHERE x.operation_id=t.operation_id AND x.state='pending' AND x.released_at IS NULL AND (x.root_id<>r.id OR ux.retired OR (x.submission_fence IS NULL AND NOT EXISTS(SELECT 1 FROM acquisition_reservation a WHERE a.operation_id=t.operation_id AND a.unit_id=ux.id AND a.candidate_id=t.candidate_id AND a.task_id=t.id AND a.source_root_id=rx.id AND a.source_generation=rx.generation AND a.source_stamp<>'' AND NOT a.legacy_conflict AND a.released_at IS NULL)) OR (x.submission_fence IS NOT NULL AND (jsonb_typeof(x.submission_fence) IS DISTINCT FROM 'object' OR (x.submission_fence->>'candidate_id') IS DISTINCT FROM t.candidate_id::text OR (x.submission_fence->>'unit_id') IS DISTINCT FROM ux.id::text OR (x.submission_fence->>'root_id') IS DISTINCT FROM rx.id::text OR (x.submission_fence->>'root_generation') IS DISTINCT FROM rx.generation::text OR (x.submission_fence->>'unit_metadata_version') IS DISTINCT FROM ux.metadata_version::text OR (x.submission_fence->>'media_metadata_version') IS DISTINCT FROM mx.metadata_version::text)))) AND NOT EXISTS(SELECT 1 FROM automatic_tv_execution_authority WHERE operation_id=t.operation_id) AND NOT EXISTS(SELECT 1 FROM automatic_tv_submission_preparation WHERE operation_id=t.operation_id) AND NOT EXISTS(SELECT 1 FROM download_requirement WHERE operation_id=t.operation_id AND (submission_fence->>'kind'='automatic_tv_episode_v1' OR submission_fence->>'goal'='upgrade')) AND NOT EXISTS(SELECT 1 FROM complete_tv_execution_authority WHERE operation_id=t.operation_id) AND NOT EXISTS(SELECT 1 FROM complete_tv_submission_preparation WHERE operation_id=t.operation_id) AND NOT EXISTS(SELECT 1 FROM complete_tv_submission_unit cu WHERE cu.task_id=t.id) AND NOT EXISTS(SELECT 1 FROM movie_upgrade_authority WHERE operation_id=t.operation_id) AND NOT EXISTS(SELECT 1 FROM unit_reservation WHERE operation_id=t.operation_id AND purpose='upgrade')),'task_stamp',encode(sha256(convert_to(jsonb_build_object('identity',jsonb_build_array(t.id,t.operation_id,t.client_id,t.candidate_id,t.info_hash,t.save_path),'demands',(SELECT jsonb_agg(jsonb_build_object('id',d.id,'unit',d.unit_id,'root',d.root_id,'actor_type',d.actor_type,'actor_id',d.actor_id,'state',d.state,'released',d.released_at AT TIME ZONE 'UTC','fence',d.submission_fence,'root_generation',rr.generation,'unit_version',u.metadata_version,'media_version',m.metadata_version,'retired',u.retired) ORDER BY d.id) FROM download_requirement d JOIN library_root rr ON rr.id=d.root_id JOIN media_unit u ON u.id=d.unit_id JOIN media m ON m.id=u.media_id WHERE d.operation_id=t.operation_id),'acquisition',(SELECT jsonb_agg(jsonb_build_array(a.id,a.unit_id,a.acquisition_lane,a.candidate_id,a.task_id,a.source_root_id,a.source_generation,a.source_stamp,a.legacy_conflict,a.released_at AT TIME ZONE 'UTC') ORDER BY a.id) FROM acquisition_reservation a WHERE a.operation_id=t.operation_id),'episode',(SELECT jsonb_build_array(ea.operation_id,ea.review_id,ea.subscription_id,ea.candidate_id,ea.unit_id,ea.root_id,ea.client_id,ea.actor_id,ea.snapshot) FROM episode_execution_authority ea WHERE ea.operation_id=t.operation_id))::text,'UTF8')),'hex'),'root',jsonb_build_object('client_id',c.id,'client_version',c.updated_at,'client_stamp',encode(sha256(convert_to(jsonb_build_object('id',c.id,'type',c.client_type,'version',c.updated_at AT TIME ZONE 'UTC','url',c.url,'username',c.username,'password',c.password_encrypted,'mapping',c.remote_path_map)::text,'UTF8')),'hex'),'mapping',CASE WHEN pg_column_size(c.remote_path_map)<=65536 THEN c.remote_path_map ELSE NULL END,'client_type',c.client_type,'root_id',r.id,'root_path',r.path,'generation',r.generation,'media_type',r.media_type,'marker',r.marker_filename,'online',r.health='online','baseline_completed',r.baseline_completed,'baseline_id',b.scan_run_id,'device',b.root_device,'inode',b.root_inode,'baseline_path',b.expected_path,'baseline_media_type',b.expected_media_type,'baseline_marker',b.expected_marker_filename)) AS material FROM download_task t JOIN download_client c ON c.id=t.client_id CROSS JOIN library_root r
LEFT JOIN LATERAL (SELECT f.scan_run_id,f.root_device,f.root_inode,f.expected_path,f.expected_media_type,f.expected_marker_filename FROM scan_finalization f JOIN scan_run s ON s.id=f.scan_run_id WHERE f.root_id=r.id AND s.generation=r.generation AND s.state='succeeded' AND f.completed_at IS NOT NULL ORDER BY s.created_at,s.id LIMIT 1) b ON true
WHERE c.id=sqlc.arg(client_id)::uuid AND r.id=sqlc.arg(root_id)::uuid
 AND t.state='tracking' AND t.id>sqlc.arg(after_id)::uuid AND (EXISTS(SELECT 1 FROM download_requirement d JOIN media_unit u ON u.id=d.unit_id JOIN media m ON m.id=u.media_id WHERE d.operation_id=t.operation_id AND d.root_id=r.id AND d.state='pending' AND d.released_at IS NULL AND NOT u.retired AND m.media_type=r.media_type AND (m.media_type='movie' OR (m.media_type='tv' AND EXISTS(SELECT 1 FROM episode_execution_authority ea WHERE ea.operation_id=t.operation_id AND ea.unit_id=u.id AND ea.root_id=r.id AND ea.client_id=t.client_id AND ea.candidate_id=t.candidate_id)))) AND NOT EXISTS(SELECT 1 FROM download_requirement x JOIN media_unit ux ON ux.id=x.unit_id JOIN media mx ON mx.id=ux.media_id JOIN library_root rx ON rx.id=x.root_id WHERE x.operation_id=t.operation_id AND x.state='pending' AND x.released_at IS NULL AND (x.root_id<>r.id OR ux.retired OR (x.submission_fence IS NULL AND NOT EXISTS(SELECT 1 FROM acquisition_reservation a WHERE a.operation_id=t.operation_id AND a.unit_id=ux.id AND a.candidate_id=t.candidate_id AND a.task_id=t.id AND a.source_root_id=rx.id AND a.source_generation=rx.generation AND a.source_stamp<>'' AND NOT a.legacy_conflict AND a.released_at IS NULL)) OR (x.submission_fence IS NOT NULL AND (jsonb_typeof(x.submission_fence) IS DISTINCT FROM 'object' OR (x.submission_fence->>'candidate_id') IS DISTINCT FROM t.candidate_id::text OR (x.submission_fence->>'unit_id') IS DISTINCT FROM ux.id::text OR (x.submission_fence->>'root_id') IS DISTINCT FROM rx.id::text OR (x.submission_fence->>'root_generation') IS DISTINCT FROM rx.generation::text OR (x.submission_fence->>'unit_metadata_version') IS DISTINCT FROM ux.metadata_version::text OR (x.submission_fence->>'media_metadata_version') IS DISTINCT FROM mx.metadata_version::text)))) AND NOT EXISTS(SELECT 1 FROM automatic_tv_execution_authority WHERE operation_id=t.operation_id) AND NOT EXISTS(SELECT 1 FROM automatic_tv_submission_preparation WHERE operation_id=t.operation_id) AND NOT EXISTS(SELECT 1 FROM download_requirement WHERE operation_id=t.operation_id AND (submission_fence->>'kind'='automatic_tv_episode_v1' OR submission_fence->>'goal'='upgrade')) AND NOT EXISTS(SELECT 1 FROM complete_tv_execution_authority WHERE operation_id=t.operation_id) AND NOT EXISTS(SELECT 1 FROM complete_tv_submission_preparation WHERE operation_id=t.operation_id) AND NOT EXISTS(SELECT 1 FROM complete_tv_submission_unit cu WHERE cu.task_id=t.id) AND NOT EXISTS(SELECT 1 FROM movie_upgrade_authority WHERE operation_id=t.operation_id) AND NOT EXISTS(SELECT 1 FROM unit_reservation WHERE operation_id=t.operation_id AND purpose='upgrade'))
ORDER BY t.id LIMIT sqlc.arg(page_size)::int;

