-- name: GuardDownloadWatchIsolation :one
SELECT isolated FROM restore_isolation WHERE singleton FOR SHARE;

-- name: LockDownloadWatchRoot :one
SELECT id FROM library_root WHERE id=$1 FOR SHARE;

-- name: LockDownloadWatchMedia :many
SELECT m.id FROM media m WHERE EXISTS(SELECT 1 FROM media_unit u JOIN download_requirement d ON d.unit_id=u.id WHERE u.media_id=m.id AND d.operation_id=$1) ORDER BY m.id FOR SHARE;

-- name: LockDownloadWatchUnits :many
SELECT u.id FROM media_unit u WHERE EXISTS(SELECT 1 FROM download_requirement d WHERE d.unit_id=u.id AND d.operation_id=$1) ORDER BY u.id FOR NO KEY UPDATE;

-- name: LockDownloadWatchDemands :many
SELECT id FROM download_requirement WHERE operation_id=$1 ORDER BY id FOR SHARE;
